using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Text.RegularExpressions;
using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.EventSystems;using UnityEditor;using TMPro;using Mewgic.Core;using Mewgic.UI;
namespace Mewgic
{
    [DefaultExecutionOrder(-10000)] public sealed class Part11EProbe:MonoBehaviour
    {
        const string Output="docs/ProductionReports/Part11/";
        public bool reload;
        readonly List<string> checks=new List<string>(),errors=new List<string>(),warnings=new List<string>();readonly Dictionary<string,string> playerKeys=new Dictionary<string,string>();
        static readonly string[] Tools={"Undo","Hint","ExtraBottle","Shuffle"};static readonly string[] Labels={"Geri Al:","İpucu:","Ek Şişe:","Karıştır:"};
        static Part11EProbe active;string key;
        void Awake(){if(active!=null){Destroy(gameObject);return;}active=this;DontDestroyOnLoad(gameObject);foreach(var suffix in new[]{"",".backup",".corrupt"}){string k=GameplayProgress.StorageKey+suffix;playerKeys[k]=PlayerPrefs.HasKey(k)?PlayerPrefs.GetString(k):null;}key=SessionState.GetString("Part11E.Key","");Bind(key);GameplayLevelCatalog.ResetSelection();Application.logMessageReceived+=Log;}
        void Bind(string profile){GameplayProgress.UseTestProfile();typeof(GameplayProgress).GetField("current",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,GameplayProgress.Open(profile));}
        void Log(string m,string s,LogType t){if(t==LogType.Warning)warnings.Add(m);if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);}
        void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add(label);}
        PrototypeApp App=>FindFirstObjectByType<PrototypeApp>();PawGuide Guide=>FindFirstObjectByType<PawGuide>();
        Puzzle Model=>(Puzzle)typeof(PrototypeApp).GetField("puzzle",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(App);
        int Selected=>(int)typeof(PrototypeApp).GetField("selected",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(App);
        string Board=>string.Join("|",Model.Export().Select(b=>string.Join(",",b)));
        string Stock=>string.Join(",",Enum.GetValues(typeof(BoosterKind)).Cast<BoosterKind>().Select(k=>GameplayProgress.Current.Remaining(k)));
        void Clean(string context){foreach(var t in FindObjectsByType<TMP_Text>(FindObjectsSortMode.None)){if(!t.enabled||!t.gameObject.activeInHierarchy)continue;string text=t.text??"";Check(!Regex.IsMatch(text,@"İpucu\s*:?\s*\d+\s*[→>]",RegexOptions.IgnoreCase)&&!text.Contains("Altın kaynak")&&!text.Contains("mavi hedef")&&!text.StartsWith("Önce kaynak")&&!text.Contains("Debug"),context+": teknik yazı yok / "+t.name);}foreach(var b in FindObjectsByType<GameplayBottleView>(FindObjectsSortMode.None))Check(b.GetComponentsInChildren<TMP_Text>(true).Length==0,context+": şişe numarası üretilmiyor");}
        void Tap(string name){var go=GameObject.Find(name);Check(go!=null,"Buton: "+name);go.GetComponent<Button>().onClick.Invoke();Clean(name);}
        IEnumerator Start(){var run=reload?Reload():Run();string failure=null;while(true){bool more=false;object next=null;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception e){failure=e.ToString();}if(!more||failure!=null)break;yield return next;}bool intact=playerKeys.All(p=>p.Value==null?!PlayerPrefs.HasKey(p.Key):PlayerPrefs.HasKey(p.Key)&&PlayerPrefs.GetString(p.Key)==p.Value);Application.logMessageReceived-=Log;GameplayProgress.RestorePlayerProfile();GameplayLevelCatalog.ResetSelection();File.WriteAllText(Output+(reload?"RELOAD_TESTS.json":"TESTS.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{success=failure==null&&errors.Count==0&&intact,failure,checks,errors,warnings,playerSaveAndBackupIntact=intact,actualPlayerPrefs=true,reload,unity=Application.unityVersion},Newtonsoft.Json.Formatting.Indented));if(reload||failure!=null){foreach(var profile in new[]{key,key+".interrupted"})foreach(var suffix in new[]{"",".backup",".corrupt"})PlayerPrefs.DeleteKey(profile+suffix);PlayerPrefs.Save();}EditorApplication.isPlaying=false;}
        IEnumerator WaitGameplay(){float until=Time.realtimeSinceStartup+8;do{yield return null;}while((Guide==null||GameObject.Find("Bottle 1")==null)&&Time.realtimeSinceStartup<until);yield return null;yield return null;}
        void Shots(string name){foreach(int h in new[]{1600,1950,2000})Capture(Output+name+(h==1600?"":"-"+h)+".png",900,h,h==2000);}
        IEnumerator Run()
        {
            yield return null;yield return null;Check(SceneManager.GetActiveScene().name=="Home"&&Guide==null,"Home üzerinde otomatik eğitim yok");Tap("Play");yield return WaitGameplay();yield return new WaitForSecondsRealtime(.25f);
            Check(Guide.State==PawGuide.Phase.Welcome&&GameObject.Find("GameplayWizardCat")!=null,"Yeni oyuncu: hazır Bölüm 1 karşılama ve mevcut kedi");Shots("Tutorial_Welcome");string original=Board,stock=Stock;
            Tap("PawNext");var move=Guide.Recommended;var solution=PuzzleSolver.Solve(Model.Export());Check(solution.Status==SearchStatus.Solved&&solution.Moves[0].Equals(move),"Kaynak/hedef doğrulanmış çözüm hamlesi");
            int wrong=Enumerable.Range(0,Model.Count).First(i=>i!=move.Source);Tap("Bottle "+(wrong+1));Check(Model.Moves==0&&Selected<0&&Guide.State==PawGuide.Phase.Source,"Yanlış kaynak aşamayı ilerletmez");yield return new WaitForSecondsRealtime(.25f);Shots("Tutorial_Source");
            for(int i=0;i<12;i++){Capture(Output+"Motion-"+i.ToString("D2")+".png",450,800);yield return new WaitForSecondsRealtime(.1f);}
            Tap("Bottle "+(move.Source+1));wrong=Enumerable.Range(0,Model.Count).First(i=>i!=move.Source&&i!=move.Target);Tap("Bottle "+(wrong+1));Check(Model.Moves==0&&Guide.State==PawGuide.Phase.Target&&!GameplayProgress.Current.TutorialCompleted(PawGuide.BasicId),"Yanlış hedef öğreticiyi tamamlamaz");yield return new WaitForSecondsRealtime(.25f);Shots("Tutorial_Target");
            Tap("Bottle "+(move.Target+1));Tap("Bottle "+(move.Target+1));Check(Model.Moves==1&&!GameplayProgress.Current.TutorialCompleted(PawGuide.BasicId),"Gerçek hamle yalnız bir kez uygulanır; animasyon beklenir");yield return new WaitForSecondsRealtime(1.1f);
            Check(Guide.State==PawGuide.Phase.Celebration&&GameplayProgress.Open(key).TutorialCompleted(PawGuide.BasicId)&&Stock==stock,"Animasyon sonrası temel eğitim diskte tamamlandı; haklar aynı");yield return new WaitForSecondsRealtime(.25f);Shots("Tutorial_Complete");
            yield return new WaitForSecondsRealtime(1.8f);Check(Guide.State==PawGuide.Phase.BoosterOffer,"Temel hamleden sonra isteğe bağlı güç daveti");Tap("PawNext");string before=Board;
            for(int i=0;i<4;i++){yield return new WaitForSecondsRealtime(.25f);Check(Guide.State==PawGuide.Phase.Boosters&&GameObject.Find("PawMessage").GetComponent<TMP_Text>().text.StartsWith(Labels[i]),"Doğru güç sırası: "+Tools[i]);Check(TopHit(Tools[i])=="PawBoosterShield","Gerçek güç dokunuşu engelleniyor: "+Tools[i]);foreach(var tool in Tools)Tap(tool);Tap("Bottle 1");Tap("Bottle 3");Check(Board==before&&Model.Moves==1&&Stock==stock,"Eğitimde hiçbir güç/şişe verisi değişmedi: "+Tools[i]);Shots(i==0?"Boosters_Guide":"Boosters_"+Tools[i]);Tap("PawNext");}
            yield return new WaitForSecondsRealtime(.3f);Check(!Guide.Visible&&GameplayProgress.Open(key).TutorialCompleted(PawGuide.BoosterId)&&Stock==stock,"Dört güç tamamlandı; diske yazıldı; stok 3/3/1/1");Shots("Gameplay_Clean");
            Tap("PawCatTouch");Tap("PawCatTouch");Check(FindObjectsByType<PawGuide>(FindObjectsSortMode.None).Length==1&&GameObject.FindObjectsByType<TMP_Text>(FindObjectsSortMode.None).Count(t=>t.name=="PawMessage")==1,"Hızlı kedi dokunuşunda tek yönetici/tek balon");yield return new WaitForSecondsRealtime(.25f);Shots("PawHelp_Menu");before=Board;Tap("Bottle 1");Check(Board==before&&Model.Moves==1,"Yardım menüsü yanlış şişe hamlesine izin vermez");Tap("PawHow");Tap("PawNext");Tap("PawNext");Check(Guide.State==PawGuide.Phase.Menu&&Board==before,"Nasıl Oynanır oyun verisini sıfırlamaz");Tap("PawBoosters");Tap("PawNext");Tap("PawClose");yield return new WaitForSecondsRealtime(.3f);Check(Stock==stock&&!Guide.Visible,"Tamamlanmış güç rehberi yeniden açılır/atlanır; hak tüketmez");
            Tap("Undo");Check(Model.Moves==0&&Board==original&&GameplayProgress.Current.Remaining(BoosterKind.Undo)==2,"Normal Undo son aktarımı geri alır");Tap("Restart");Check(Model.Moves==0&&!Guide.Visible,"Restart öğrenilmiş eğitimi açmaz");
            Tap("Hint");Check(FindObjectsByType<HintCueGraphic>(FindObjectsSortMode.None).Length==2&&GameplayProgress.Current.Remaining(BoosterKind.Hint)==2&&Model.Moves==0,"Gerçek Hint metinsiz iki işaret ve mevcut hak kullanır");Tap("Hint");Check(GameplayProgress.Current.Remaining(BoosterKind.Hint)==2,"Aynı ipucu ikinci hak tüketmez");Tap("Restart");
            Tap("Pause");Check(App.IsPaused,"Pause açılır");before=Board;Tap("Bottle 1");Tap("Bottle 3");Check(Board==before&&Model.Moves==0,"Pause sırasında hamle yok");Tap("Resume");Tap("PawCatTouch");Tap("Pause");Check(App.IsPaused&&!Guide.Visible,"Pause açık yardımı kapatır");Tap("Resume");yield return new WaitForSecondsRealtime(.3f);
            // Extension contract, without introducing a new game mechanic.
            var def=ScriptableObject.CreateInstance<PawTutorialDefinition>();def.tutorialId="qa.part11e.feature.v1";def.conditionKey="qa-condition";def.completionKey="qa-finish";def.message="Yeni özellik rehberi test mesajı.";def.targetName="Bottle 1";
            Check(!Guide.TryStartFeature(def,false)&&Guide.TryStartFeature(def,true),"Yeni mekanik tanımı: koşul ve benzersiz ID girişi");Check(!Guide.CompleteFeature("wrong")&&Guide.CompleteFeature("qa-finish")&&GameplayProgress.Open(key).TutorialCompleted(def.tutorialId),"Yeni mekanik doğru tamamlanma anahtarıyla kaydedilir");Check(!Guide.TryStartFeature(def,true),"Tamamlanan yeni mekanik tekrarlanmaz");Destroy(def);yield return new WaitForSecondsRealtime(.3f);
            solution=PuzzleSolver.Solve(Model.Export());foreach(var m in solution.Moves){Tap("Bottle "+(m.Source+1));Tap("Bottle "+(m.Target+1));yield return new WaitForSecondsRealtime(1.1f);}Check(Model.Won&&FindFirstObjectByType<GameplayEndScreen>().IsShowing&&GameplayProgress.Current.BestStars(1)>0,"Şişe sıralama kazanma/ödül/yıldız kaydı");
            Tap("NextLevel");yield return WaitGameplay();Check(GameplayLevelCatalog.SelectedId==2&&!Guide.Visible&&Model.Moves==0,"Bölüm 1 → 2: doğru gerçek bölüm; otomatik eğitim yok");Tap("Home");yield return null;yield return null;Check(SceneManager.GetActiveScene().name=="Home","Gameplay → Home");Tap("Play");yield return WaitGameplay();Check(!Guide.Visible,"Mevcut oyuncu yeniden oynarken eğitim yok");
            // Separate isolated disk save for interrupted first tutorial.
            Bind(key+".interrupted");GameplayLevelCatalog.ResetSelection();SceneManager.LoadScene("Gameplay");yield return WaitGameplay();Tap("PawNext");move=Guide.Recommended;Tap("Bottle "+(move.Source+1));Tap("PawClose");yield return new WaitForSecondsRealtime(.3f);Check(!Guide.Visible&&!GameplayProgress.Open(key+".interrupted").TutorialCompleted(PawGuide.BasicId),"Yarım eğitim tamamlandı kaydedilmez");Tap("Restart");Check(!Guide.Visible&&Model.Moves==0,"Yarım eğitimde Restart normal oynanışa döner");
            Bind(key+".interrupted");SceneManager.LoadScene("Gameplay");yield return WaitGameplay();Check(Guide.State==PawGuide.Phase.Welcome,"Yarım eğitimin diskten yeniden girişinde güvenli baştan başlama");Tap("PawNext");move=Guide.Recommended;Tap("Bottle "+(move.Source+1));Bind(key+".interrupted");SceneManager.LoadScene("Gameplay");yield return WaitGameplay();Check(Guide.State==PawGuide.Phase.Welcome,"Hedef aşamasında çıkıştan sonra güvenli yeniden başlama");Tap("PawClose");yield return new WaitForSecondsRealtime(.3f);Tap("PawCatTouch");Tap("PawClose");yield return new WaitForSecondsRealtime(.3f);
            Bind(key);SceneManager.LoadScene("Gameplay");yield return WaitGameplay();Check(!Guide.Visible&&GameplayProgress.Current.TutorialCompleted(PawGuide.BasicId)&&GameplayProgress.Current.TutorialCompleted(PawGuide.BoosterId),"Öğrenilmiş ana test profiline dönüşte öğreticiler yok");SessionState.SetString("Part11E.Expected",JsonUtility.ToJson(GameplayProgress.Current.Snapshot));Clean("Test sonu");
        }
        IEnumerator Reload(){yield return WaitGameplay();yield return new WaitForSecondsRealtime(.25f);Check(!Guide.Visible&&GameplayProgress.Current.TutorialCompleted(PawGuide.BasicId)&&GameplayProgress.Current.TutorialCompleted(PawGuide.BoosterId),"Play Mode çıkış/yeniden giriş: tamamlanan eğitim açılmaz");Check(JsonUtility.ToJson(GameplayProgress.Current.Snapshot)==SessionState.GetString("Part11E.Expected",""),"Gerçek diskten bütün test oyuncu verileri aynı");Check(GameplayProgress.Current.BestStars(1)>0,"Yeniden girişte bölüm yıldız/ödül kaydı korunur");Tap("PawCatTouch");Check(Guide.State==PawGuide.Phase.Menu,"Yeniden girişte kediden yardım alınabilir");Tap("PawBoosters");Check(Guide.State==PawGuide.Phase.Boosters,"Yeniden girişte güç rehberi tekrar açılabilir");Tap("PawClose");yield return new WaitForSecondsRealtime(.3f);Clean("Yeniden giriş sonu");}
        Rect Bounds(RectTransform r,RectTransform relative){var c=new Vector3[4];r.GetWorldCorners(c);var a=(Vector2)relative.InverseTransformPoint(c[0]);var b=(Vector2)relative.InverseTransformPoint(c[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
        void AuditLayout(RectTransform safe,int height)
        {
            var go=GameObject.Find("PawBubble");if(go==null||safe==null)return;var area=Bounds((RectTransform)go.transform,safe);Check(area.xMin>=safe.rect.xMin&&area.xMax<=safe.rect.xMax&&area.yMin>=safe.rect.yMin&&area.yMax<=safe.rect.yMax,"Balon Safe Area içinde: "+height);
            foreach(var view in FindObjectsByType<GameplayBottleView>(FindObjectsSortMode.None))Check(!area.Overlaps(Bounds(view.Rig,safe)),"Açıklama şişeyi örtmüyor: "+height);
            foreach(var t in go.GetComponentsInChildren<TMP_Text>()){t.ForceMeshUpdate();Check(!t.isTextOverflowing,"Açıklama/metin taşmıyor: "+t.name+height);}
            if(Guide.State==PawGuide.Phase.Boosters){int page=Array.FindIndex(Labels,l=>GameObject.Find("PawMessage").GetComponent<TMP_Text>().text.StartsWith(l));var marker=GameObject.Find("PawHighlight").GetComponent<RectTransform>();var target=GameObject.Find(Tools[page]).GetComponent<RectTransform>();var m=Bounds(marker,safe);var r=Bounds(target,safe);Check(Vector2.Distance(m.center,r.center)<1,"Doğru güç vurgulanıyor: "+Tools[page]+height);Check(m.yMax+28<area.yMin,"Pati konuşma balonuna çarpmıyor: "+height);Check(FindObjectsByType<PawHighlight>(FindObjectsSortMode.None).Length==1,"Aynı anda tek güç vurgusu");}
        }
        string TopHit(string name)
        {
            var canvas=FindFirstObjectByType<Canvas>();var camera=Camera.main;var mode=canvas.renderMode;var oldCam=canvas.worldCamera;var target=camera.targetTexture;float distance=canvas.planeDistance;var rt=new RenderTexture(900,1600,24);
            try {camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();FindFirstObjectByType<GameplayPresentation>().Layout();Guide.SendMessage("LateUpdate");Canvas.ForceUpdateCanvases();var rect=GameObject.Find(name).GetComponent<RectTransform>();var point=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(camera,rect.TransformPoint(rect.rect.center))};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(point,hits);return hits.Count>0?hits[0].gameObject.name:"";}
            finally{camera.targetTexture=target;canvas.renderMode=mode;canvas.worldCamera=oldCam;canvas.planeDistance=distance;rt.Release();DestroyImmediate(rt);Canvas.ForceUpdateCanvases();FindFirstObjectByType<GameplayPresentation>().Layout();Guide.SendMessage("LateUpdate");}
        }

        void Capture(string filename,int width,int height,bool inset=false)
        {
            var canvas=FindFirstObjectByType<Canvas>();var camera=Camera.main;var p=FindFirstObjectByType<HomeCharacterPresenter>();var safe=p!=null?(RectTransform)p.transform.Find("UI"):(GameObject.Find("Safe area")??GameObject.Find("MapSafeArea"))?.GetComponent<RectTransform>();
            var mode=canvas.renderMode;var oldCam=canvas.worldCamera;float distance=canvas.planeDistance;var oldTarget=camera.targetTexture;var oldActive=RenderTexture.active;Vector2 min=safe!=null?safe.anchorMin:Vector2.zero,max=safe!=null?safe.anchorMax:Vector2.one;
            var rt=new RenderTexture(width,height,24);var tex=new Texture2D(width,height,TextureFormat.RGB24,false);
            try{
                camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;if(inset&&safe!=null){safe.anchorMin=new Vector2(.035f,.04f);safe.anchorMax=new Vector2(.965f,.955f);}
                Canvas.ForceUpdateCanvases();var gameplay=FindFirstObjectByType<GameplayPresentation>();if(gameplay!=null)gameplay.Layout();var pause=GameObject.Find("PauseSafeArea");if(pause!=null&&safe!=null){var pr=(RectTransform)pause.transform;pr.anchorMin=safe.anchorMin;pr.anchorMax=safe.anchorMax;}if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}var map=FindFirstObjectByType<Mewgic.Map.MapWorld>();if(map!=null)map.Layout();var daily=FindFirstObjectByType<Mewgic.Daily.DailyActivitiesPanel>();if(daily!=null&&daily.IsOpen)daily.Layout();var hub=FindFirstObjectByType<Mewgic.Rewards.RewardHubPanel>();if(hub!=null&&hub.IsOpen)hub.Layout();Canvas.ForceUpdateCanvases();
                foreach(var text in FindObjectsByType<TMPro.TMP_Text>(FindObjectsSortMode.None))text.ForceMeshUpdate();FindFirstObjectByType<Mewgic.UI.PawGuide>()?.SendMessage("LateUpdate");foreach(var text in FindObjectsByType<TMP_Text>(FindObjectsSortMode.None)){text.ForceMeshUpdate();if(text.name=="PawMessage")Check(!text.isTextOverflowing,"Pati balonunda taşma yok: "+height);}AuditLayout(safe,height);Clean("Görsel "+filename);camera.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes(filename,tex.EncodeToPNG());
            }finally{camera.targetTexture=oldTarget;canvas.renderMode=mode;canvas.worldCamera=oldCam;canvas.planeDistance=distance;if(safe!=null){safe.anchorMin=min;safe.anchorMax=max;}RenderTexture.active=oldActive;DestroyImmediate(tex);rt.Release();DestroyImmediate(rt);Canvas.ForceUpdateCanvases();if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}}
        }
    }
}
